use std::env;
use std::error::Error;
use std::fmt;
use std::fs::File;
use std::io::{self, BufReader, BufWriter};

use payments_engine::engine::Engine;
use payments_engine::{process, write_accounts};

fn main() -> Result<(), MainError> {
    let args: Vec<String> = env::args().collect();
    let [_, path] = args.as_slice() else {
        return Err("usage: payments-engine <transactions.csv>".into());
    };

    // The whole state: client accounts and the deposits still disputable.
    let mut engine = Engine::new();

    let file = File::open(path)?;
    process(&mut BufReader::new(file), &mut engine)?;
    write_accounts(&engine, &mut BufWriter::new(io::stdout().lock()))?;
    Ok(())
}

/// Any error, reported by `main` with its message.
///
/// Rust prints the error returned by `main` with `Debug`, which for most
/// errors is a structure dump. This wrapper prints the `Display` message
/// instead, and converts from any error so that `?` works.
struct MainError(Box<dyn Error>);

impl<E: Into<Box<dyn Error>>> From<E> for MainError {
    fn from(err: E) -> Self {
        MainError(err.into())
    }
}

impl fmt::Debug for MainError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(&self.0, f)
    }
}

